import java.util.*;
import java.io.*;

public class Main {
    static final long HUGE_INF = (long)1e9 + 9;
    static final long INF = Long.MAX_VALUE;
    static int n, m, T;
    static int s, t;
    static List<List<Integer>> adj;
    static List<Edge> edges;
    static String[] sci = new String[101], reac = new String[101];
    static int[][] turnsUnusable = new int[10][10];
    static int[][] visited = new int[101][101];
    static int[] ptr, dist;
    static boolean[][] reach = new boolean[10][10][10][10];

    static class Edge {
        int u, v;
        long flow, capacity;
        Edge(int u, int v, long flow, long capacity) {
            this.u = u;
            this.v = v;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static boolean valid(int r, int c) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    static int getID(int x, int y) {
        return 1 + m * x + y;
    }

    static void addEdge(int u, int v, long cap) {
        adj.get(u).add(edges.size());
        edges.add(new Edge(u, v, 0, cap));
        adj.get(v).add(edges.size());
        edges.add(new Edge(v, u, 0, 0));
    }

    static boolean bfs() {
        Arrays.fill(dist, -1);
        dist[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int id : adj.get(u)) {
                Edge e = edges.get(id);
                int v = e.v;
                if (dist[v] == -1 && e.flow < e.capacity) {
                    dist[v] = dist[u] + 1;
                    q.offer(v);
                    if (v == t) return true;
                }
            }
        }
        return false;
    }

    static long augment(int u, long flow) {
        if (flow == 0 || u == t) return flow;
        for (; ptr[u] < adj.get(u).size(); ++ptr[u]) {
            int id = adj.get(u).get(ptr[u]);
            Edge e = edges.get(id);
            int v = e.v;
            if (dist[v] == dist[u] + 1 && e.flow < e.capacity) {
                long pushed = augment(v, Math.min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    edges.get(id ^ 1).flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static long maxFlow() {
        long totalFlow = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            long pushed;
            while ((pushed = augment(s, Long.MAX_VALUE)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int T_input = Integer.parseInt(br.readLine());
        T = T_input + 1;
        n = m = Integer.parseInt(br.readLine());
        s = 0;
        t = m * m * 2 + 1;
        adj = new ArrayList<>();
        for (int i = 0; i <= t; i++) {
            adj.add(new ArrayList<>());
        }
        edges = new ArrayList<>();
        ptr = new int[t + 1];
        dist = new int[t + 1];

        for (int i = 0; i < n; i++) {
            sci[i] = br.readLine();
        }
        for (int i = 0; i < n; i++) {
            reac[i] = br.readLine();
            for (int j = 0; j < m; j++) {
                turnsUnusable[i][j] = (int) HUGE_INF;
                if (reac[i].charAt(j) == 'Z') {
                    Queue<int[]> qz = new LinkedList<>();
                    qz.offer(new int[]{i, j});
                    turnsUnusable[i][j] = 1;
                }
            }
        }

        // BFS for 'Z'
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (reac[i].charAt(j) == 'Z') {
                    Queue<int[]> qz = new LinkedList<>();
                    qz.offer(new int[]{i, j});
                    while (!qz.isEmpty()) {
                        int[] pos = qz.poll();
                        int x = pos[0], y = pos[1];
                        for (int dx = -1; dx <= 1; dx++) {
                            for (int dy = -1; dy <= 1; dy++) {
                                if (Math.abs(dx) + Math.abs(dy) == 1) {
                                    int nx = x + dx, ny = y + dy;
                                    if (valid(nx, ny) && turnsUnusable[nx][ny] == (int) HUGE_INF && sci[nx].charAt(ny) != 'Y') {
                                        turnsUnusable[nx][ny] = turnsUnusable[x][y] + 1;
                                        qz.offer(new int[]{nx, ny});
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Build graph
        for (int x = 0; x < n; x++) {
            for (int y = 0; y < m; y++) {
                if (sci[x].charAt(y) >= '1' && sci[x].charAt(y) <= '9') {
                    addEdge(s, getID(x, y), sci[x].charAt(y) - '0');
                }
                if (reac[x].charAt(y) >= '1' && reac[x].charAt(y) <= '9') {
                    addEdge(n * n + getID(x, y), t, reac[x].charAt(y) - '0');
                }
                for (int X = 0; X < n; X++) {
                    for (int Y = 0; Y < m; Y++) {
                        if (sci[x].charAt(y) == 'Y' || sci[x].charAt(y) == 'Z' || reac[X].charAt(Y) == 'Y' || reac[X].charAt(Y) == 'Z') continue;
                        for (int xx = 0; xx < n; xx++) {
                            for (int yy = 0; yy < m; yy++) {
                                for (int dx = -1; dx <= 1; dx++) {
                                    for (int dy = -1; dy <= 1; dy++) {
                                        if (Math.abs(dx) + Math.abs(dy) == 1) {
                                            int nx = xx + dx, ny = yy + dy;
                                            if (valid(nx, ny) && !visited[nx][ny] && sci[nx].charAt(ny) != 'Y' && sci[nx].charAt(ny) != 'Z' && (1 + Math.abs(xx - x) + Math.abs(yy - y)) <= turnsUnusable[nx][ny]) {
                                                // BFS for path
                                                for (int[] row : visited) Arrays.fill(row, 0);
                                                Queue<int[]> q = new LinkedList<>();
                                                q.offer(new int[]{x, y, 1});
                                                visited[x][y] = 1;
                                                boolean found = false;
                                                while (!q.isEmpty()) {
                                                    int[] curr = q.poll();
                                                    int xx2 = curr[0], yy2 = curr[1], t_curr = curr[2];
                                                    if (xx2 == X && yy2 == Y) {
                                                        visited[X][Y] = 1;
                                                        found = true;
                                                        break;
                                                    }
                                                    if (t_curr >= turnsUnusable[xx2][yy2] || t_curr >= T) continue;
                                                    for (int ddx = -1; ddx <= 1; ddx++) {
                                                        for (int ddy = -1; ddy <= 1; ddy++) {
                                                            if (Math.abs(ddx) + Math.abs(ddy) == 1) {
                                                                int nxx = xx2 + ddx, nyy = yy2 + ddy;
                                                                if (valid(nxx, nyy) && visited[nxx][nyy] == 0 && sci[nxx].charAt(nyy) != 'Y' && sci[nxx].charAt(nyy) != 'Z' && t_curr + 1 <= turnsUnusable[nxx][nyy]) {
                                                                    visited[nxx][nyy] = 1;
                                                                    q.offer(new int[]{nxx, nyy, t_curr + 1});
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                                if (visited[X][Y] == 1) {
                                                    addEdge(getID(x, y), n * n + getID(X, Y), INF);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        long maxFlowVal = maxFlow();
        System.out.println(maxFlowVal);
    }
}

